/* =====================================================================
   Solveurs guidés : matériaux de construction et technologie
   ===================================================================== */
(function(){
'use strict';
const S = A.SOL, {nf, ns, R, plot, SV, T, Ln, Pth, Rc, Ci, Dim, C} = S.U, need = S.need, Err = S.Err;
const tb = (h, rows) => `| ${h.join(' | ')} |\n| ${h.map(() => '---').join(' | ')} |\n` + rows.map(r => `| ${r.join(' | ')} |`).join('\n');
const rad = d => d*Math.PI/180, deg = r => r*180/Math.PI;

/* ---------------- MATÉRIAUX ---------------- */
const MF = [5, 2.5, 1.25, .63, .315, .16];
S.reg({id:'mat-granulo', mat:'mat', niv:1, titre:'Analyse granulométrique d\'un sable et module de finesse', resume:'Refus cumulés, tamisats, courbe granulométrique, module de finesse et classement du sable.',
 champs:[{k:'t', l:'Tamis et refus partiels', t:'tab', min:3, max:14, cols:[{k:'d', l:'Tamis', u:'mm'}, {k:'m', l:'Refus partiel', u:'g'}], row:() => ({d:.08, m:0})}, {k:'fond', l:'Passant au dernier tamis (fond)', u:'g'}],
 ex:{t:[{d:5, m:12}, {d:2.5, m:85}, {d:1.25, m:160}, {d:.63, m:245}, {d:.315, m:210}, {d:.16, m:160}, {d:.08, m:70}], fond:58},
 rnd:() => { const base = [R.s(0, 30, 1), R.s(40, 140, 1), R.s(100, 220, 1), R.s(150, 280, 1), R.s(120, 260, 1), R.s(80, 200, 1), R.s(30, 90, 1)]; return {t:[5, 2.5, 1.25, .63, .315, .16, .08].map((d, i) => ({d, m:base[i]})), fond:R.s(20, 80, 1)}; },
 enonce:p => `On a tamisé un échantillon de sable (masse sèche totale ${nf(p.t.reduce((a, r) => a + (+r.m || 0), 0) + (+p.fond || 0))} g). Les refus partiels sont :\n\n${tb(['Tamis (mm)', ...p.t.map(r => nf(r.d, 3)), 'Fond'], [['Refus (g)', ...p.t.map(r => nf(r.m)), nf(p.fond)]])}\n\n1. Calculer les refus cumulés et les pourcentages de refus et de tamisats.\n2. Tracer la courbe granulométrique.\n3. Calculer le module de finesse et conclure sur l'emploi de ce sable dans un béton.`,
 solve(p){
  const t = p.t.map(r => ({d:+r.d, m:+r.m})).sort((a, b) => b.d - a.d); if(t.some(r => !(r.d > 0) || !(r.m >= 0))) throw new Err('Tamis ou masse invalide.'); need(p, [['fond', 'Fond', 0]]);
  const M = t.reduce((a, r) => a + r.m, 0) + p.fond; if(!(M > 0)) throw new Err('Masse totale nulle.');
  let cum = 0; t.forEach(r => { cum += r.m; r.cum = cum; r.pr = cum/M*100; r.pt = 100 - r.pr; });
  const used = MF.map(d => t.find(r => Math.abs(r.d - d) < .006)), Mf = used.reduce((a, r) => a + (r ? r.pr : 0), 0)/100, miss = MF.filter((d, i) => !used[i]), st = [];
  st.push({t:'Refus cumulés et tamisats', md:`$$ masse totale M = Σ refus + fond = ${nf(M, 1)} g\n\n${tb(['Tamis (mm)', 'Refus partiel (g)', 'Refus cumulé (g)', 'Refus cumulé (%)', 'Tamisat (%)'], t.map(r => [nf(r.d, 3), nf(r.m), nf(r.cum), nf(r.pr, 1), nf(r.pt, 1)]))}\n\nRefus cumulé = somme des refus du tamis et de tous les tamis plus gros ; tamisat = 100 − refus cumulé.`, ask:[{l:`Tamisat au tamis ${nf(t[Math.min(3, t.length - 1)].d, 3)} mm`, v:t[Math.min(3, t.length - 1)].pt, u:'%', abs:.2}], hint:'Additionnez les refus de haut en bas, puis divisez par la masse totale.'});
  const W = 520, H = 260, lx = d => Math.log10(d), x0 = lx(.063), x1 = lx(8), X = d => 50 + (lx(d) - x0)/(x1 - x0)*(W - 70), Y = v => 20 + (1 - v/100)*(H - 60);
  let g = ''; [0, 20, 40, 60, 80, 100].forEach(v => { g += Ln(50, Y(v), W - 20, Y(v), {c:'#E3DFD7', w:1, d:v ? '3 4' : ''}) + T(44, Y(v) + 4, String(v), {a:'end', s:10, c:C.GR}); });
  [.08, .16, .315, .63, 1.25, 2.5, 5].forEach(d => { g += Ln(X(d), 20, X(d), H - 40, {c:'#E3DFD7', w:1}) + T(X(d), H - 26, nf(d, 3), {a:'middle', s:10, c:C.GR}); });
  g += Pth('M' + t.slice().reverse().map(r => X(r.d).toFixed(1) + ',' + Y(r.pt).toFixed(1)).join(' L'), {c:C.OR, w:2.4}) + t.map(r => Ci(X(r.d), Y(r.pt), 3, {f:C.OR, c:C.OR})).join('') + T(W - 20, H - 8, 'tamis (mm, échelle logarithmique)', {a:'end', s:10.5, c:C.GR}) + T(54, 14, 'tamisats (%)', {s:10.5, c:C.GR});
  st.push({t:'Courbe granulométrique', md:'On porte les **tamisats** en fonction de l\'ouverture des tamis, sur une échelle **logarithmique** : la courbe montre la répartition des grains, du plus fin au plus gros.', html:`<div class="solfig">${SV(W, H, g, 'Courbe granulométrique')}</div>`});
  st.push({t:'Module de finesse', md:`$$ Mf = (Σ refus cumulés en % aux tamis 0,16 – 0,315 – 0,63 – 1,25 – 2,5 – 5 mm) / 100\n$$ Mf = (${used.map(r => r ? nf(r.pr, 1) : '0').join(' + ')}) / 100 = ${nf(Mf, 2)}\n${miss.length ? `Tamis absents (comptés à 0) : ${miss.join(', ')} mm.\n` : ''}${Mf < 1.8 ? 'Mf < 1,8 : sable **trop fin** (forte demande en eau, résistance plus faible).' : Mf < 2.2 ? '1,8 ≤ Mf < 2,2 : sable **fin**, convient pour les enduits ; à corriger pour un béton.' : Mf <= 2.8 ? '2,2 ≤ Mf ≤ 2,8 : **bon sable à béton** (plage recommandée).' : Mf <= 3.2 ? '2,8 < Mf ≤ 3,2 : sable **grossier** : béton résistant mais moins maniable.' : 'Mf > 3,2 : sable **trop grossier**.'}`, ask:[{l:'Mf', v:Mf, abs:.02}]});
  return {steps:st, bilan:`Module de finesse **${nf(Mf, 2)}** → ${Mf < 1.8 ? 'sable trop fin' : Mf < 2.2 ? 'sable fin' : Mf <= 2.8 ? 'bon sable à béton' : Mf <= 3.2 ? 'sable grossier' : 'sable trop grossier'}.`};
 }});

const EAU = {ferme:[180, 'ferme (affaissement 0 à 4 cm)'], plast:[195, 'plastique (5 à 9 cm)'], tplast:[210, 'très plastique (10 à 15 cm)']};
const DCOR = {10:1.12, 12.5:1.09, 16:1.04, 20:1, 25:.97, 31.5:.94};
S.reg({id:'mat-dreux', mat:'mat', mats:['mat', 'tech'], niv:2, titre:'Composition d\'un béton (méthode simplifiée de Dreux-Gorisse)', resume:'Résistance visée, rapport C/E, dosage en eau et en ciment, volumes absolus des granulats et dosage par sac.',
 champs:[{k:'fc', l:'Résistance à 28 jours demandée fc28', u:'MPa'}, {k:'cl', l:'Ciment', t:'sel', o:[[45, 'CEM II 32,5 (classe vraie ≈ 45 MPa)'], [55, 'CEM I/II 42,5 (classe vraie ≈ 55 MPa)']]}, {k:'G', l:'Qualité des granulats (coefficient G)', t:'sel', o:[[.45, 'Courante (0,45)'], [.5, 'Bonne (0,50)'], [.55, 'Excellente (0,55)']]},
  {k:'D', l:'Dmax des granulats', t:'sel', o:Object.keys(DCOR).map(k => [+k, k + ' mm'])}, {k:'cons', l:'Consistance', t:'sel', o:Object.entries(EAU).map(([k, v]) => [k, v[1]])}, {k:'ps', l:'Part du sable dans les granulats', u:'%'}, {k:'V', l:'Volume à fabriquer', u:'m³'}],
 ex:{fc:25, cl:45, G:.5, D:20, cons:'plast', ps:38, V:6},
 rnd:() => ({fc:R.p([20, 25, 30]), cl:R.p([45, 55]), G:R.p([.45, .5, .55]), D:R.p([12.5, 16, 20, 25]), cons:R.p(['ferme', 'plast', 'tplast']), ps:R.s(34, 42, 1), V:R.s(1, 12, .5)}),
 enonce:p => `On doit couler **${nf(p.V)} m³** de béton armé de résistance **fc28 = ${nf(p.fc)} MPa**, de consistance ${EAU[p.cons][1]}, avec un ciment ${+p.cl === 55 ? 'CEM 42,5' : 'CEM 32,5'} et des granulats de Dmax = ${nf(p.D)} mm (qualité G = ${nf(p.G)}). Les granulats contiennent ${nf(p.ps)} % de sable en volume.\n\n1. Calculer la résistance visée et le rapport C/E (formule de Bolomey).\n2. Déterminer le dosage en eau et en ciment.\n3. Calculer les masses de sable et de gravier pour 1 m³.\n4. En déduire les quantités pour le chantier et le dosage pratique pour un sac de 50 kg.`,
 solve(p){
  need(p, [['fc', 'fc28', 10, 50], ['ps', '% sable', 20, 60], ['V', 'Volume', .05]]);
  const fv = 1.15*p.fc, CE = fv/(+p.G*+p.cl) + .5, E = EAU[p.cons][0]*DCOR[p.D], C0 = CE*E, Cm = 300, Cc = Math.max(C0, Cm);
  const Vg = 1000 - Cc/3.1 - E - 20, Vs = Vg*p.ps/100, Vgr = Vg - Vs, Ms = Vs*2.65, Mg = Vgr*2.65, sacs = Math.ceil(Cc*p.V/50), st = [];
  st.push({t:'Résistance visée et rapport C/E', md:`On vise une résistance moyenne majorée de 15 % (dispersion du chantier) :\n$$ f'28 = 1,15 × fc28 = ${nf(fv, 2)} MPa\nFormule de Bolomey : $$ f'28 = G × σ'c × (C/E − 0,5)\n$$ C/E = f'28 / (G σ'c) + 0,5 = ${nf(fv, 2)} / (${nf(+p.G)} × ${nf(+p.cl)}) + 0,5 = ${nf(CE, 3)}`, ask:[{l:'C/E', v:CE, abs:.01}], hint:'Isolez C/E dans la formule de Bolomey.'});
  st.push({t:'Dosage en eau et en ciment', md:`Eau de gâchage pour une consistance ${EAU[p.cons][1]} et Dmax = 20 mm : ${EAU[p.cons][0]} l/m³, corrigée pour Dmax = ${nf(p.D)} mm (× ${nf(DCOR[p.D], 2)}) :\n$$ E = ${nf(E, 0)} l/m³\n$$ C = (C/E) × E = ${nf(CE, 3)} × ${nf(E, 0)} = ${nf(C0, 0)} kg/m³\n${C0 < Cm ? `Inférieur au minimum de ${Cm} kg/m³ pour un béton armé : on retient **C = ${Cm} kg/m³**.` : `On retient **C = ${nf(Cc, 0)} kg/m³** (≈ ${nf(Cc/50, 1)} sacs de 50 kg par m³).`}`, ask:[{l:'E', v:E, u:'l/m³', abs:2}, {l:'C retenu', v:Cc, u:'kg/m³', abs:3}]});
  st.push({t:'Granulats (méthode des volumes absolus)', md:`1 m³ de béton = volume absolu du ciment + de l'eau + de l'air (≈ 20 l) + des granulats :\n$$ V granulats = 1000 − C/3,1 − E − 20 = 1000 − ${nf(Cc/3.1, 1)} − ${nf(E, 0)} − 20 = ${nf(Vg, 1)} l\n$$ V sable = ${nf(p.ps)} % × ${nf(Vg, 1)} = ${nf(Vs, 1)} l   →   ${nf(Ms, 0)} kg  (masse volumique absolue 2,65)\n$$ V gravier = ${nf(Vgr, 1)} l   →   ${nf(Mg, 0)} kg\n\n${tb(['Constituant', 'Pour 1 m³', `Pour ${nf(p.V)} m³`], [['Ciment', nf(Cc, 0) + ' kg', nf(Cc*p.V, 0) + ' kg (' + sacs + ' sacs)'], ['Eau', nf(E, 0) + ' l', nf(E*p.V, 0) + ' l'], ['Sable', nf(Ms, 0) + ' kg', nf(Ms*p.V/1000, 2) + ' t'], ['Gravier', nf(Mg, 0) + ' kg', nf(Mg*p.V/1000, 2) + ' t']])}`, ask:[{l:'Masse de sable pour 1 m³', v:Ms, u:'kg', tol:.03}]});
  const k50 = 50/Cc, bs = Ms*k50/1500*1000/60, bg = Mg*k50/1400*1000/60;
  st.push({t:'Dosage pratique par sac de 50 kg', md:`Pour un sac de ciment : ${nf(Ms*k50, 0)} kg de sable, ${nf(Mg*k50, 0)} kg de gravier et ${nf(E*k50, 0)} l d'eau.\nEn volumes apparents (sable ≈ 1,5 t/m³, gravier ≈ 1,4 t/m³, brouette de 60 l) :\n- sable : **${nf(Ms*k50/1.5, 0)} l** ≈ ${nf(bs, 1)} brouette(s)\n- gravier : **${nf(Mg*k50/1.4, 0)} l** ≈ ${nf(bg, 1)} brouette(s)\n- eau : **${nf(E*k50, 0)} l** (à ajuster selon l'humidité du sable)\n\n> [!attention]\n> Méthode simplifiée : les proportions exactes se règlent par une **gâchée d'essai** et des éprouvettes.`, ask:[{l:'Nombre de sacs pour le chantier', v:sacs, abs:.5}]});
  return {steps:st, bilan:`C/E = ${nf(CE, 2)} ; par m³ : **${nf(Cc, 0)} kg** de ciment, **${nf(E, 0)} l** d'eau, **${nf(Ms, 0)} kg** de sable, **${nf(Mg, 0)} kg** de gravier ; ${sacs} sacs pour ${nf(p.V)} m³.`};
 }});

const EPR = {cyl:['Cylindre 16 × 32 cm', Math.PI*16*16/4], cube:['Cube 15 cm', 225]};
const CLS = {20:['C20/25', 20, 25], 25:['C25/30', 25, 30], 30:['C30/37', 30, 37]};
S.reg({id:'mat-fck', mat:'mat', niv:2, titre:'Écrasement d\'éprouvettes : résistance moyenne, écart-type, conformité', resume:'Contraintes de rupture, moyenne, écart-type, résistance caractéristique estimée et critères de conformité.',
 champs:[{k:'ep', l:'Éprouvettes', t:'sel', o:Object.entries(EPR).map(([k, v]) => [k, v[0]])}, {k:'cls', l:'Classe demandée', t:'sel', o:Object.entries(CLS).map(([k, v]) => [+k, v[0]])}, {k:'F', l:'Forces de rupture', t:'tab', min:3, max:15, cols:[{k:'f', l:'F', u:'kN'}], row:() => ({f:600})}],
 ex:{ep:'cyl', cls:25, F:[{f:612}, {f:585}, {f:640}, {f:598}, {f:571}, {f:625}]},
 rnd:() => { const ep = R.p(['cyl', 'cube']), cls = R.p([20, 25, 30]), fm = (ep === 'cyl' ? CLS[cls][1] : CLS[cls][2]) + R.s(-1, 9, .5), S0 = EPR[ep][1]; return {ep, cls, F:Array.from({length:R.i(3, 8)}, () => ({f:Math.round((fm + R.s(-3.5, 3.5, .1))*S0/10)}))}; },
 enonce:p => `Le laboratoire a écrasé à 28 jours des éprouvettes (${EPR[p.ep][0].toLowerCase()}) prélevées sur le béton d'un chantier commandé en **${CLS[p.cls][0]}**. Forces de rupture : ${p.F.map(r => nf(r.f) + ' kN').join(' ; ')}.\n\n1. Calculer la résistance de chaque éprouvette.\n2. Calculer la moyenne et l'écart-type.\n3. Estimer la résistance caractéristique et vérifier la conformité du béton.`,
 solve(p){
  const F = p.F.map(r => +r.f); if(F.some(v => !(v > 0))) throw new Err('Force invalide.'); const n = F.length, S0 = EPR[p.ep][1];
  const f = F.map(v => v*1000/(S0*100)), fm = f.reduce((a, v) => a + v, 0)/n, s = Math.sqrt(f.reduce((a, v) => a + (v - fm)**2, 0)/(n - 1)), fk = fm - 1.64*s, fmin = Math.min(...f);
  const fck = p.ep === 'cyl' ? CLS[p.cls][1] : CLS[p.cls][2], ok1 = fm >= fck + 4, ok2 = fmin >= fck - 4, st = [];
  st.push({t:'Résistance de chaque éprouvette', md:`$$ f = F / S   avec S = ${nf(S0, 1)} cm² = ${nf(S0*100, 0)} mm²\n\n${tb(['Éprouvette', 'F (kN)', 'f (MPa)'], F.map((v, i) => [i + 1, nf(v), nf(f[i], 2)]))}`, ask:[{l:'f de l\'éprouvette 1', v:f[0], u:'MPa'}], hint:'F en N (× 1000) divisée par la section en mm² donne des MPa.'});
  st.push({t:'Moyenne et écart-type', md:`$$ fm = Σf / n = ${nf(fm, 2)} MPa\n$$ s = √( Σ(f − fm)² / (n − 1) ) = ${nf(s, 2)} MPa\nCoefficient de variation : s/fm = ${nf(s/fm*100, 1)} % ${s/fm < .08 ? '(béton homogène)' : s/fm < .15 ? '(dispersion moyenne)' : '(forte dispersion : fabrication à améliorer)'}`, ask:[{l:'fm', v:fm, u:'MPa'}, {l:'s', v:s, u:'MPa'}]});
  st.push({t:'Résistance caractéristique et conformité', md:`Résistance caractéristique estimée (5 % de valeurs inférieures) : $$ fk ≈ fm − 1,64 s = ${nf(fk, 2)} MPa\nCritères de conformité pour un petit nombre de résultats (production initiale, NF EN 206) avec fck = ${nf(fck)} MPa (${p.ep === 'cyl' ? 'cylindre' : 'cube'}) :\n- critère 1 : fm ≥ fck + 4 = ${nf(fck + 4)} MPa → ${ok1 ? '✓' : '✗'} (fm = ${nf(fm, 2)})\n- critère 2 : chaque résultat ≥ fck − 4 = ${nf(fck - 4)} MPa → ${ok2 ? '✓' : '✗'} (minimum ${nf(fmin, 2)})\n\n${ok1 && ok2 ? `**Le béton est conforme** à la classe ${CLS[p.cls][0]}.` : `**Le béton n'est pas conforme** : informer le bureau de contrôle, carottages éventuels et vérification de la formule (eau, ciment).`}`, ask:[{l:'fk', v:fk, u:'MPa', abs:Math.abs(fk)*.02 + .05}]});
  return {steps:st, bilan:`fm = **${nf(fm, 1)} MPa**, s = ${nf(s, 2)} MPa, fk ≈ ${nf(fk, 1)} MPa → ${ok1 && ok2 ? '**conforme**' : '**non conforme**'} à ${CLS[p.cls][0]}.`};
 }});

/* ---------------- TECHNOLOGIE ---------------- */
S.reg({id:'tech-escalier', mat:'tech', mats:['tech', 'math', 'dessin'], niv:1, titre:'Calcul d\'un escalier droit (loi de Blondel)', resume:'Nombre et hauteur de marches, giron, longueur de la volée, inclinaison, paillasse et longueur de trémie.',
 ia:'{"H":3.06,"hc":17,"emm":1,"epl":20} — H hauteur à monter (m), hc hauteur de marche souhaitée (cm), emm emmarchement (m), epl épaisseur du plancher haut (cm)',
 champs:[{k:'H', l:'Hauteur à monter (sol fini à sol fini)', u:'m'}, {k:'hc', l:'Hauteur de marche souhaitée', u:'cm'}, {k:'emm', l:'Emmarchement (largeur)', u:'m'}, {k:'epl', l:'Épaisseur du plancher haut', u:'cm'}],
 ex:{H:3.06, hc:17, emm:1, epl:20},
 rnd:() => ({H:R.s(2.7, 3.4, .01), hc:R.p([16, 17, 18]), emm:R.p([.9, 1, 1.2]), epl:R.p([16, 20, 25])}),
 enonce:p => `On doit construire un escalier droit en béton armé pour monter **${nf(p.H)} m** (de sol fini à sol fini), avec une hauteur de marche voisine de **${nf(p.hc)} cm** et un emmarchement de ${nf(p.emm)} m. Le plancher haut a ${nf(p.epl)} cm d'épaisseur.\n\n1. Déterminer le nombre de marches et leur hauteur exacte.\n2. Calculer le giron avec la loi de Blondel et vérifier le confort.\n3. Calculer la longueur de la volée, son inclinaison et l'épaisseur de la paillasse.\n4. Calculer la longueur minimale de la trémie (échappée de 2,00 m).`,
 solve(p){
  need(p, [['H', 'Hauteur', .5, 6], ['hc', 'Hauteur de marche', 13, 21], ['emm', 'Emmarchement', .6], ['epl', 'Épaisseur', 10, 40]]);
  const n = Math.round(p.H*100/p.hc), h = p.H/n, g = .63 - 2*h, Bl = 2*h + g, L = (n - 1)*g, al = Math.atan(h/g), ram = Math.hypot(L, p.H - h), ep = Math.max(.12, Math.ceil(ram/30*100)/100), Lt = (2 + p.epl/100)/Math.tan(al), st = [];
  st.push({t:'Nombre et hauteur des marches', md:`$$ n = H / h souhaitée = ${nf(p.H*100, 0)} / ${nf(p.hc)} = ${nf(p.H*100/p.hc, 2)}  →  n = ${n} marches\n$$ h = H / n = ${nf(p.H*100, 0)} / ${n} = ${nf(h*100, 2)} cm\nToutes les marches doivent avoir **exactement la même hauteur** (une marche différente fait trébucher).`, ask:[{l:'n', v:n, abs:.01}, {l:'h', v:h*100, u:'cm', abs:.05}]});
  st.push({t:'Giron (loi de Blondel)', md:`Loi de Blondel (confort de la foulée) : $$ 60 cm ≤ 2h + g ≤ 64 cm   → on prend 2h + g = 63 cm\n$$ g = 63 − 2 × ${nf(h*100, 2)} = ${nf(g*100, 2)} cm\n${g < .25 ? 'g < 25 cm : escalier raide, à réserver aux escaliers de service.' : g > .32 ? 'Giron large : escalier très doux, il prend beaucoup de place.' : 'Giron compris entre 25 et 32 cm : **escalier confortable** ✓'}`, ask:[{l:'g', v:g*100, u:'cm', abs:.1}]});
  st.push({t:'Volée, inclinaison et paillasse', md:`Une volée de ${n} marches comporte **${n - 1} girons** (la dernière marche arrive sur le palier) :\n$$ L = (n − 1) × g = ${n - 1} × ${nf(g*100, 2)} = ${nf(L*100, 1)} cm = ${nf(L, 2)} m\n$$ α = arctan(h / g) = ${nf(deg(al), 1)}°\nLongueur rampante de la paillasse : $$ √(L² + (H − h)²) = ${nf(ram, 2)} m\nÉpaisseur de paillasse : $$ e ≈ rampant / 30 = ${nf(ram*100/30, 1)} cm  →  e = ${nf(ep*100, 0)} cm (minimum 12 cm)`, ask:[{l:'L', v:L, u:'m', abs:.01}, {l:'α', v:deg(al), u:'°', abs:.2}]});
  st.push({t:'Longueur de la trémie', md:`Pour garder une **échappée** (hauteur libre au-dessus du nez des marches) d'au moins 2,00 m, le plancher haut doit être ouvert sur :\n$$ Lt = (2,00 + épaisseur du plancher) / tan α = (2,00 + ${nf(p.epl/100, 2)}) / ${nf(Math.tan(al), 4)} = ${nf(Lt, 2)} m\nOn prévoit une trémie de **${nf(Math.ceil(Lt*10)/10, 1)} m × ${nf(p.emm + .1, 2)} m** (emmarchement + jeu).`, ask:[{l:'Lt', v:Lt, u:'m', abs:.02}],
   html:(() => { const k = 300/Math.max(L, p.H), x0 = 40, y0 = 280; let d = `M${x0},${y0}`; for(let i = 0; i < n; i++){ d += ` L${(x0 + i*g*k).toFixed(1)},${(y0 - (i + 1)*h*k).toFixed(1)}`; if(i < n - 1) d += ` L${(x0 + (i + 1)*g*k).toFixed(1)},${(y0 - (i + 1)*h*k).toFixed(1)}`; }
     const xe = x0 + L*k, ytop = y0 - p.H*k; let g2 = Pth(d, {c:C.INK, w:2}) + Rc(xe, ytop, 120, p.epl/100*k, {f:C.CO}) + Rc(x0 + (L - Lt)*k - 120, ytop, 120, p.epl/100*k, {f:C.CO});
     g2 += Ln(x0 + (L - Lt)*k, ytop + p.epl/100*k, x0 + (L - Lt)*k, ytop + p.epl/100*k + 2*k, {c:C.RD, w:1.4, d:'4 3'}) + Dim(x0 + (L - Lt)*k, ytop - 12, xe, ytop - 12, 'trémie ' + nf(Lt, 2) + ' m') + Dim(x0, y0 + 16, xe, y0 + 16, 'L = ' + nf(L, 2) + ' m') + Dim(x0 - 16, y0, x0 - 16, ytop, 'H = ' + nf(p.H, 2) + ' m') + T(x0 + (L - Lt)*k + 6, ytop + p.epl/100*k + k, '≥ 2,00 m', {s:10.5, c:C.RD});
     return `<div class="solfig">${SV(480, 320, g2, 'Escalier en coupe')}</div>`; })()});
  return {steps:st, bilan:`**${n} marches** de ${nf(h*100, 1)} cm, giron **${nf(g*100, 1)} cm**, volée de ${nf(L, 2)} m (α = ${nf(deg(al), 1)}°), paillasse ${nf(ep*100, 0)} cm, trémie **${nf(Lt, 2)} m**.`};
 }});

S.reg({id:'tech-toiture', mat:'tech', mats:['tech', 'metre', 'dessin'], niv:1, titre:'Toiture à deux versants : pente, rampant, tôles et pannes', resume:'Hauteur au faîtage, longueur de rampant, surface de couverture, nombre de tôles, faîtières, pannes et fermes.',
 champs:[{k:'l', l:'Largeur du bâtiment (portée)', u:'m'}, {k:'Lb', l:'Longueur du bâtiment', u:'m'}, {k:'pe', l:'Pente', u:'°'}, {k:'d', l:'Débords (avant-toits et pignons)', u:'m'},
  {k:'tole', l:'Couverture', t:'sel', w:1, o:[['bac', 'Bac aluminium sur mesure (largeur utile 1,00 m)'], ['ond', 'Tôle ondulée 2,00 × 0,90 m (largeur utile 0,80 m)']]}, {k:'ep', l:'Entraxe des pannes', u:'m'}, {k:'ef', l:'Entraxe des fermes', u:'m'}],
 ex:{l:9, Lb:12, pe:15, d:.6, tole:'bac', ep:1.2, ef:3},
 rnd:() => ({l:R.s(6, 12, .5), Lb:R.s(8, 20, .5), pe:R.s(10, 30, 1), d:R.p([.4, .5, .6, .8]), tole:R.p(['bac', 'ond']), ep:R.p([1, 1.1, 1.2]), ef:R.p([2.5, 3, 3.5])}),
 enonce:p => `Une maison de **${nf(p.l)} m × ${nf(p.Lb)} m** reçoit une toiture à deux versants de pente **${nf(p.pe)}°**, avec des débords de ${nf(p.d)} m tout autour. Couverture : ${p.tole === 'bac' ? 'bacs aluminium sur mesure (largeur utile 1,00 m)' : 'tôles ondulées de 2,00 × 0,90 m (largeur utile 0,80 m, recouvrement 0,20 m)'} ; pannes tous les ${nf(p.ep)} m ; fermes tous les ${nf(p.ef)} m (pignons en maçonnerie).\n\n1. Calculer la hauteur au faîtage et la longueur du rampant.\n2. Calculer la surface de couverture.\n3. Calculer le nombre de tôles, de faîtières, de pannes et de fermes.`,
 solve(p){
  need(p, [['l', 'Largeur', 2], ['Lb', 'Longueur', 2], ['pe', 'Pente', 3, 60], ['d', 'Débords', 0, 2], ['ep', 'Entraxe pannes', .5, 2], ['ef', 'Entraxe fermes', 1, 6]]);
  const a = rad(p.pe), f = p.l/2*Math.tan(a), r = (p.l/2 + p.d)/Math.cos(a), Lc = p.Lb + 2*p.d, Sx = 2*r*Lc;
  let nt, txt; if(p.tole === 'bac'){ const nc = Math.ceil(Lc/1); nt = 2*nc; txt = `Bacs sur mesure : un bac par largeur de 1,00 m, de la longueur du rampant (${nf(r + .05, 2)} m avec 5 cm de dépassement en égout).\n$$ colonnes par versant = ${nf(Lc, 2)} / 1,00 → ${nc}\n$$ nombre de bacs = 2 × ${nc} = ${nt} bacs de ${nf(r + .05, 2)} m`; }
  else { const nc = Math.ceil(Lc/.8), nr = Math.max(1, Math.ceil((r - .2)/1.8)); nt = 2*nc*nr; txt = `Tôles de 2,00 m avec recouvrement de 0,20 m : chaque rang couvre 1,80 m.\n$$ colonnes par versant = ${nf(Lc, 2)} / 0,80 → ${nc}\n$$ rangs = (${nf(r, 2)} − 0,20) / 1,80 → ${nr}\n$$ nombre de tôles = 2 × ${nc} × ${nr} = ${nt}`; }
  const nfa = Math.ceil(Lc/.9), np = Math.ceil(r/p.ep) + 1, Lp = 2*np*Lc, nfe = Math.max(0, Math.ceil(p.Lb/p.ef) - 1), st = [];
  st.push({t:'Hauteur au faîtage et rampant', md:`$$ f = (l/2) × tan α = ${nf(p.l/2, 2)} × tan ${nf(p.pe)}° = ${nf(f, 3)} m\n$$ rampant = (l/2 + débord) / cos α = ${nf(p.l/2 + p.d, 2)} / cos ${nf(p.pe)}° = ${nf(r, 3)} m\nPente en % : ${nf(Math.tan(a)*100, 1)} % ${p.pe < 10 ? '(attention : pente faible, risque d\'infiltration avec des tôles ondulées)' : ''}`, ask:[{l:'f', v:f, u:'m', abs:.005}, {l:'Rampant', v:r, u:'m', abs:.005}]});
  st.push({t:'Surface de couverture', md:`$$ longueur couverte = ${nf(p.Lb)} + 2 × ${nf(p.d)} = ${nf(Lc, 2)} m\n$$ S = 2 versants × rampant × longueur = 2 × ${nf(r, 3)} × ${nf(Lc, 2)} = ${nf(Sx, 2)} m²`, ask:[{l:'S', v:Sx, u:'m²'}]});
  st.push({t:'Tôles, faîtières, pannes et fermes', md:`${txt}\n$$ faîtières (longueur utile 0,90 m) = ${nf(Lc, 2)} / 0,90 → ${nfa}\n$$ pannes par versant = rampant / entraxe + 1 = ${nf(r, 2)} / ${nf(p.ep)} + 1 → ${np}  ⇒  ${2*np} files de ${nf(Lc, 2)} m = ${nf(Lp, 1)} m de pannes\n$$ fermes = ${nf(p.Lb)} / ${nf(p.ef)} − 1 → ${nfe} fermes intermédiaires (les pignons maçonnés portent les extrémités)\nPrévoir aussi les tire-fonds ou crochets (≈ 5 par m², soit ${Math.ceil(Sx*5)}), les closoirs et l'étanchéité des rives.`, ask:[{l:'Nombre de tôles ou bacs', v:nt, abs:.5}, {l:'Nombre de files de pannes', v:2*np, abs:.5}],
   html:(() => { const k = 26, w = (p.l + 2*p.d)*k, x0 = 40, yb = 200; return `<div class="solfig">${SV(w + 80, 240, Rc(x0 + p.d*k, yb - 70, p.l*k, 70, {f:C.CO}) + Pth(`M${x0},${yb - 70 + p.d*Math.tan(a)*k} L${x0 + w/2},${yb - 70 - f*k} L${x0 + w},${yb - 70 + p.d*Math.tan(a)*k}`, {c:'#C95F18', w:3}) + Dim(x0 + w/2 + 18, yb - 70 - f*k, x0 + w/2 + 18, yb - 70, 'f = ' + nf(f, 2) + ' m') + T(x0 + w/4 - 20, yb - 80 - f*k/2, 'rampant ' + nf(r, 2) + ' m', {s:11, r:-p.pe}) + Dim(x0 + p.d*k, yb + 14, x0 + (p.d + p.l)*k, yb + 14, 'l = ' + nf(p.l) + ' m'), 'Pignon')}</div>`; })()});
  return {steps:st, bilan:`Faîtage à **${nf(f, 2)} m**, rampant **${nf(r, 2)} m**, couverture **${nf(Sx, 1)} m²** : **${nt}** ${p.tole === 'bac' ? 'bacs' : 'tôles'}, ${nfa} faîtières, ${nf(Lp, 0)} m de pannes, ${nfe} fermes.`};
 }});

const DOS = {150:['Béton de propreté / gros béton', 75], 250:['Béton non armé (dallage léger, regards)', 125], 300:['Fondations, semelles', 150], 350:['Béton armé courant (poteaux, poutres, dalles)', 175], 400:['Béton armé fortement sollicité', 190]};
S.reg({id:'tech-gachee', mat:'tech', mats:['tech', 'mat', 'metre'], niv:1, titre:'Dosage d\'un béton sur chantier (sacs, seaux, brouettes)', resume:'Quantités de ciment, sable, gravier et eau pour un volume de béton, et proportions pour une gâchée d\'un sac.',
 champs:[{k:'V', l:'Volume de béton à fabriquer', u:'m³'}, {k:'dos', l:'Dosage', t:'sel', w:1, o:Object.entries(DOS).map(([k, v]) => [+k, `${k} kg/m³ — ${v[0]}`])}, {k:'pert', l:'Pertes', u:'%'}],
 ex:{V:2.4, dos:350, pert:5},
 rnd:() => ({V:R.s(.3, 8, .1), dos:R.p([150, 250, 300, 350, 400]), pert:R.p([3, 5, 8])}),
 enonce:p => `Sur un chantier sans centrale, on doit fabriquer **${nf(p.V)} m³** de béton dosé à **${nf(p.dos)} kg/m³** (${DOS[p.dos][0].toLowerCase()}). Composition courante pour 1 m³ : ${nf(p.dos)} kg de ciment, 400 l de sable, 800 l de gravier et environ ${DOS[p.dos][1]} l d'eau. On compte ${nf(p.pert)} % de pertes.\n\n1. Calculer les quantités de ciment (en sacs de 50 kg), de sable, de gravier et d'eau.\n2. Donner les proportions pour une gâchée d'un sac (en seaux de 10 l et en brouettes de 60 l).`,
 solve(p){
  need(p, [['V', 'Volume', .01], ['pert', 'Pertes', 0, 30]]); const k = 1 + p.pert/100, V = p.V*k, Cm = p.dos*V, sacs = Math.ceil(Cm/50), Sm = .4*V, Gm = .8*V, Em = DOS[p.dos][1]*V, per = 50/p.dos, st = [];
  st.push({t:'Volume avec pertes', md:`$$ V = ${nf(p.V)} × (1 + ${nf(p.pert)}/100) = ${nf(V, 3)} m³`, ask:[{l:'V', v:V, u:'m³'}]});
  st.push({t:'Quantités de matériaux', md:`${tb(['Matériau', 'Pour 1 m³', `Pour ${nf(V, 2)} m³`], [['Ciment', nf(p.dos) + ' kg', `${nf(Cm, 0)} kg = **${sacs} sacs** de 50 kg`], ['Sable', '400 l', `**${nf(Sm, 2)} m³**`], ['Gravier', '800 l', `**${nf(Gm, 2)} m³**`], ['Eau', DOS[p.dos][1] + ' l', `${nf(Em, 0)} l`]])}\n\nOn arrondit **toujours au sac supérieur**. Le sable et le gravier se commandent en m³ (camion benne de 6 à 10 m³).`, ask:[{l:'Nombre de sacs', v:sacs, abs:.5}, {l:'Sable', v:Sm, u:'m³'}, {l:'Gravier', v:Gm, u:'m³'}]});
  st.push({t:'Gâchée d\'un sac de ciment', md:`Un sac (50 kg) correspond à 50/${nf(p.dos)} = ${nf(per, 3)} m³ de béton. Pour ce sac :\n- sable : 400 × ${nf(per, 3)} = **${nf(400*per, 0)} l** ≈ ${nf(400*per/10, 1)} seaux ou ${nf(400*per/60, 1)} brouette(s)\n- gravier : 800 × ${nf(per, 3)} = **${nf(800*per, 0)} l** ≈ ${nf(800*per/10, 1)} seaux ou ${nf(800*per/60, 1)} brouette(s)\n- eau : **${nf(DOS[p.dos][1]*per, 0)} l** ≈ ${nf(DOS[p.dos][1]*per/10, 1)} seaux (moins si le sable est mouillé)\n\nNombre de gâchées : **${sacs}**.\n\n> [!astuce] Bonnes pratiques\n> Mélanger d'abord à sec ciment + sable + gravier, puis ajouter l'eau progressivement. Un béton trop mouillé perd beaucoup de résistance.`, ask:[{l:'Sable par sac', v:400*per, u:'l', abs:1}]});
  return {steps:st, bilan:`**${sacs} sacs** de ciment, **${nf(Sm, 2)} m³** de sable, **${nf(Gm, 2)} m³** de gravier, ${nf(Em, 0)} l d'eau ; par sac : ${nf(400*per, 0)} l de sable, ${nf(800*per, 0)} l de gravier, ${nf(DOS[p.dos][1]*per, 0)} l d'eau.`};
 }});
/* ---------------- DESSIN TECHNIQUE ET ARCHITECTURAL ---------------- */
const FMT = {A0:[1189, 841], A1:[841, 594], A2:[594, 420], A3:[420, 297], A4:[297, 210]};
const ECH = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000];
S.reg({id:'des-echelle', mat:'dessin', niv:1, titre:'Choisir l\'échelle et le format d\'un plan', resume:'Zone utile de la feuille, échelle maximale, échelle normalisée retenue, dimensions sur le papier, place du cartouche et précision graphique.',
 ia:'{"L":14.4,"l":10.8,"fmt":"A3","cot":3,"cw":18,"ch":5} — L et l dimensions réelles de l\'objet (m), fmt format "A0" à "A4", cot place des cotes de chaque côté (cm), cw et ch largeur et hauteur du cartouche (cm)',
 champs:[{k:'L', l:'Longueur réelle de l\'objet', u:'m'}, {k:'l', l:'Largeur réelle de l\'objet', u:'m'}, {k:'fmt', l:'Format de la feuille (horizontale)', t:'sel', o:Object.keys(FMT).map(k => [k, `${k} — ${FMT[k][0]} × ${FMT[k][1]} mm`])}, {k:'cot', l:'Place des cotes de chaque côté', u:'cm'}, {k:'cw', l:'Largeur du cartouche', u:'cm'}, {k:'ch', l:'Hauteur du cartouche', u:'cm'}],
 ex:{L:14.4, l:10.8, fmt:'A3', cot:3, cw:18, ch:5},
 rnd:() => ({L:R.s(6, 30, .1), l:R.s(4, 18, .1), fmt:R.p(['A3', 'A2', 'A1']), cot:R.p([2, 3, 4]), cw:18, ch:R.p([4, 5, 6])}),
 enonce:p => `Un bâtiment de **${nf(p.L)} m × ${nf(p.l)} m** doit être dessiné sur une feuille **${p.fmt}** horizontale (cadre à 20 mm à gauche et 10 mm ailleurs), avec **${nf(p.cot)} cm** de cotes de chaque côté et un cartouche de **${nf(p.cw)} × ${nf(p.ch)} cm**.\n\n1. Calculer la zone utile de la feuille.\n2. Déterminer l'échelle maximale théorique puis l'échelle normalisée à retenir.\n3. Donner les dimensions du dessin sur le papier et la place du cartouche.\n4. Calculer ce que représente 1 cm du plan et la précision graphique (0,1 mm sur le papier).`,
 solve(p){
  need(p, [['L', 'Longueur', .01, 100000], ['l', 'Largeur', .01, 100000], ['cot', 'Place des cotes', 0, 20], ['cw', 'Largeur du cartouche', 0, 40], ['ch', 'Hauteur du cartouche', 0, 20]]);
  const F = FMT[p.fmt]; if(!F) throw new Err('Format inconnu.');
  const Wu = (F[0] - 30)/10, Hu = (F[1] - 20)/10, a = Math.max(p.L, p.l), b = Math.min(p.L, p.l);
  if(Wu - 2*p.cot <= 0 || Hu - 2*p.cot <= 0) throw new Err('Les cotes occupent toute la feuille : réduisez leur place.');
  const under = E => a*100/E + 2*p.cot <= Wu && b*100/E + 2*p.cot + p.ch <= Hu, side = E => a*100/E + 2*p.cot + p.cw <= Wu && b*100/E + 2*p.cot <= Hu;
  const Emin = Math.max(a*100/(Wu - 2*p.cot), b*100/(Hu - 2*p.cot)), E0 = ECH.find(e => e >= Emin - 1e-9), E = ECH.find(e => e >= Emin - 1e-9 && (under(e) || side(e)));
  if(!E) throw new Err('L\'objet est trop grand pour ce format, même au 1/5 000 : choisissez un format plus grand.');
  const w = a*100/E, h = b*100/E, pos = under(E) ? 'sous le dessin' : 'à côté du dessin', st = [];
  st.push({t:'Zone utile de la feuille', md:`Format ${p.fmt} horizontal : ${F[0]} × ${F[1]} mm. On retire le cadre (20 mm à gauche + 10 mm à droite, 10 mm en haut et en bas) :\n$$ largeur utile = ${F[0]} − 30 = ${F[0] - 30} mm = ${nf(Wu, 1)} cm\n$$ hauteur utile = ${F[1]} − 20 = ${F[1] - 20} mm = ${nf(Hu, 1)} cm\nOn place la grande dimension de l'objet (${nf(a)} m) dans la longueur de la feuille.`, ask:[{l:'Largeur utile', v:Wu, u:'cm', abs:.05}, {l:'Hauteur utile', v:Hu, u:'cm', abs:.05}]});
  st.push({t:'Échelle maximale et échelle normalisée', md:`Place disponible pour le dessin seul (cotes déduites) : ${nf(Wu - 2*p.cot, 1)} × ${nf(Hu - 2*p.cot, 1)} cm.\n$$ E ≤ ${nf(Wu - 2*p.cot, 1)} / ${nf(a*100, 0)} = 1/${nf(a*100/(Wu - 2*p.cot), 1)}      E ≤ ${nf(Hu - 2*p.cot, 1)} / ${nf(b*100, 0)} = 1/${nf(b*100/(Hu - 2*p.cot), 1)}\nL'échelle maximale théorique est donc **1/${nf(Emin, 1)}**. On prend l'échelle **normalisée** immédiatement plus petite : **1/${E0}**${E0 !== E ? `, mais le cartouche ne trouve alors sa place ni dessous ni à côté du dessin : on descend au **1/${E}**` : ''}.\n\nÉchelles normalisées : 1/1, 1/2, 1/5, 1/10, 1/20, 1/50, 1/100, 1/200, 1/500, 1/1 000…`, ask:[{l:'Dénominateur de l\'échelle retenue', v:E, abs:.5}], hint:'Divisez la place disponible (en cm) par la dimension réelle (en cm), pour la longueur et pour la largeur ; gardez la plus petite échelle.'});
  const k = 300/Math.max(Wu, Hu*1.4), sw = Wu*k, sh = Hu*k, x0 = 40, y0 = 20, dx = x0 + p.cot*k, dy = y0 + p.cot*k;
  const fig = Rc(x0 - 2*k, y0 - 1*k, (F[0]/10)*k, (F[1]/10)*k, {c:C.GR, w:1}) + Rc(x0, y0, sw, sh, {w:2}) + Rc(dx, dy, w*k, h*k, {f:C.CO, w:1.6}) + T(dx + w*k/2, dy + h*k/2 + 4, `${nf(a)} × ${nf(b)} m au 1/${E}`, {a:'middle', s:11, b:1}) +
   Rc(x0 + sw - p.cw*k, y0 + sh - p.ch*k, p.cw*k, p.ch*k, {f:'#E4EDFC', c:C.BL}) + T(x0 + sw - p.cw*k/2, y0 + sh - p.ch*k/2 + 4, 'cartouche', {a:'middle', s:10, c:C.BL}) + Dim(dx, dy + h*k + 10, dx + w*k, dy + h*k + 10, nf(w, 1) + ' cm');
  st.push({t:'Dimensions sur le papier', md:`$$ ${nf(a*100, 0)} cm / ${E} = ${nf(w, 2)} cm      ${nf(b*100, 0)} cm / ${E} = ${nf(h, 2)} cm\nAvec les cotes : **${nf(w + 2*p.cot, 1)} × ${nf(h + 2*p.cot, 1)} cm**, dans une zone utile de ${nf(Wu, 1)} × ${nf(Hu, 1)} cm. Le cartouche (${nf(p.cw)} × ${nf(p.ch)} cm) se place **${pos}**, en bas à droite.${E >= 500 ? '\n\nÀ cette échelle, le dessin convient à un plan de masse ou de situation.' : E <= 20 ? '\n\nÀ cette échelle, il s\'agit d\'un dessin de détail.' : ''}`, ask:[{l:'Longueur sur le papier', v:w, u:'cm', abs:.05}, {l:'Largeur sur le papier', v:h, u:'cm', abs:.05}], html:`<div class="solfig">${SV(x0 + sw + 30, y0 + sh + 40, fig, 'Mise en page')}</div>`});
  st.push({t:'Lecture et précision', md:`Au 1/${E} : $$ 1 cm sur le plan = ${nf(E/100, 2)} m en réalité\nUn trait de crayon fait environ 0,1 mm : $$ précision graphique = 0,1 mm × ${E} = ${nf(E/10, 1)} mm = ${nf(E/100, 3)} m\nLes dimensions plus petites que cette précision ne peuvent pas être lues à la règle : elles doivent être **cotées**.`, ask:[{l:'1 cm représente', v:E/100, u:'m', abs:.001}]});
  return {steps:st, bilan:`Zone utile ${nf(Wu, 1)} × ${nf(Hu, 1)} cm ; échelle maximale 1/${nf(Emin, 1)} → **1/${E}** ; dessin **${nf(w, 1)} × ${nf(h, 1)} cm** (${nf(w + 2*p.cot, 1)} × ${nf(h + 2*p.cot, 1)} cm avec les cotes), cartouche ${pos}.`};
 }});

S.reg({id:'des-surfaces', mat:'dessin', mats:['dessin', 'metre'], niv:2, titre:'Tableau des surfaces, emprise, CES et COS', resume:'Surfaces des pièces, surface habitable, emprise, rapport habitable / emprise, surface de plancher, CES et COS comparés au règlement.',
 ia:'{"t":[{"n":"Séjour","lo":5.4,"la":6.6,"nb":1,"ty":"h"}],"Le":10,"le":7,"ep":20,"niv":1,"S":400,"ces":0.5,"cos":1} — t liste des pièces (n nom, lo et la dimensions intérieures en m, nb nombre de pièces identiques, ty "h" habitable ou "a" annexe), Le et le dimensions extérieures du bâtiment (m), ep épaisseur des murs de façade (cm), niv nombre de niveaux identiques, S surface de la parcelle (m²), ces et cos valeurs maximales du règlement',
 champs:[{k:'t', l:'Pièces (cotes intérieures)', t:'tab', min:1, max:30, cols:[{k:'n', l:'Pièce', t:'txt', w:110}, {k:'lo', l:'Longueur', u:'m', w:60}, {k:'la', l:'Largeur', u:'m', w:60}, {k:'nb', l:'Nombre', w:44}, {k:'ty', l:'Type', t:'sel', o:[['h', 'Habitable'], ['a', 'Annexe']]}], row:() => ({n:'Pièce', lo:3, la:3, nb:1, ty:'h'})},
  {k:'Le', l:'Longueur extérieure du bâtiment', u:'m'}, {k:'le', l:'Largeur extérieure du bâtiment', u:'m'}, {k:'ep', l:'Épaisseur des murs de façade', u:'cm'}, {k:'niv', l:'Nombre de niveaux identiques'}, {k:'S', l:'Surface de la parcelle', u:'m²'}, {k:'ces', l:'CES maximal du règlement'}, {k:'cos', l:'COS maximal du règlement'}],
 ex:{t:[{n:'Séjour', lo:6.0, la:6.6, nb:1, ty:'h'}, {n:'Chambre', lo:3.6, la:3.4, nb:3, ty:'h'}, {n:'Cuisine', lo:3.0, la:2.8, nb:1, ty:'h'}, {n:'Douche-WC', lo:2.0, la:1.6, nb:2, ty:'h'}, {n:'Couloir', lo:5.0, la:1.1, nb:1, ty:'h'}, {n:'Magasin', lo:2.0, la:1.8, nb:1, ty:'a'}], Le:13.4, le:9.4, ep:20, niv:1, S:450, ces:.5, cos:1},
 rnd:() => { const t = [{n:'Séjour', lo:R.s(4.5, 7, .1), la:R.s(4, 6, .1), nb:1, ty:'h'}, {n:'Chambre', lo:R.s(3, 4, .1), la:R.s(3, 3.8, .1), nb:R.i(2, 4), ty:'h'}, {n:'Cuisine', lo:R.s(2.6, 3.6, .1), la:R.s(2.4, 3.2, .1), nb:1, ty:'h'}, {n:'Salle d\'eau', lo:R.s(1.8, 2.6, .1), la:R.s(1.5, 2, .1), nb:R.i(1, 3), ty:'h'}, {n:'Couloir', lo:R.s(4, 8, .1), la:R.p([1, 1.1, 1.2]), nb:1, ty:'h'}];
  const Sr = t.reduce((a, r) => a + r.lo*r.la*r.nb, 0), le = R.s(8, 11, .1), Le = Math.max(le, Math.ceil(Sr/R.s(.72, .85, .01)/le*10)/10);
  return {t, Le, le, ep:R.p([15, 20]), niv:R.i(1, 3), S:R.p([400, 450, 500, 600, 800]), ces:R.p([.4, .5, .6]), cos:R.p([.8, 1, 1.2])}; },
 enonce:p => `Un bâtiment de **${nf(p.Le)} × ${nf(p.le)} m** (murs de façade de ${nf(p.ep)} cm, ${p.niv} niveau${p.niv > 1 ? 'x identiques' : ''}) est construit sur une parcelle de **${nf(p.S)} m²**. Le règlement impose **CES ≤ ${nf(p.ces, 2)}** et **COS ≤ ${nf(p.cos, 2)}**. Pièces d'un niveau (cotes intérieures) :\n\n${tb(['Pièce', 'Dimensions (m)', 'Nombre', 'Type'], p.t.map(r => [r.n, `${nf(r.lo)} × ${nf(r.la)}`, r.nb, r.ty === 'a' ? 'annexe' : 'habitable']))}\n\n1. Calculer la surface de chaque pièce et la surface habitable d'un niveau.\n2. Calculer l'emprise et le rapport surface habitable / emprise.\n3. Calculer la surface de plancher totale.\n4. Calculer le CES et le COS et conclure.`,
 solve(p){
  need(p, [['Le', 'Longueur extérieure', 1], ['le', 'Largeur extérieure', 1], ['ep', 'Épaisseur des murs', 5, 60], ['niv', 'Nombre de niveaux', 1, 30], ['S', 'Surface de la parcelle', 1], ['ces', 'CES', .01, 1], ['cos', 'COS', .01, 20]]);
  const rows = p.t.map(r => ({n:r.n || 'Pièce', lo:+r.lo, la:+r.la, nb:Math.max(1, Math.round(+r.nb || 1)), ty:r.ty === 'a' ? 'a' : 'h'})); if(rows.some(r => !(r.lo > 0) || !(r.la > 0))) throw new Err('Dimension de pièce invalide.');
  rows.forEach(r => { r.s = r.lo*r.la; r.st = r.s*r.nb; });
  const Sh = rows.filter(r => r.ty === 'h').reduce((a, r) => a + r.st, 0), Sa = rows.filter(r => r.ty === 'a').reduce((a, r) => a + r.st, 0), Em = p.Le*p.le, e = p.ep/100;
  if(Sh + Sa > Em) throw new Err('Les pièces occupent plus que l\'emprise du bâtiment : vérifiez les dimensions.');
  const Sp1 = (p.Le - 2*e)*(p.le - 2*e), Sp = Sp1*p.niv, ces = Em/p.S, cos = Sp/p.S, ok1 = ces <= p.ces + 1e-9, ok2 = cos <= p.cos + 1e-9, st = [];
  st.push({t:'Surfaces des pièces', md:`${tb(['Pièce', 'Calcul', 'Surface'], rows.map(r => [r.n + (r.ty === 'a' ? ' (annexe)' : ''), `${r.nb > 1 ? r.nb + ' × ' : ''}${nf(r.lo, 2)} × ${nf(r.la, 2)}`, nf(r.st, 2) + ' m²']))}\n\n$$ surface habitable d'un niveau = ${nf(Sh, 2)} m²${Sa ? `      annexes : ${nf(Sa, 2)} m²` : ''}\nLes annexes (magasin, garage, terrasse, véranda ouverte) ne comptent pas dans la surface habitable.`, ask:[{l:'Surface de la 1re pièce', v:rows[0].st, u:'m²'}, {l:'Surface habitable d\'un niveau', v:Sh, u:'m²'}]});
  st.push({t:'Emprise et efficacité du plan', md:`$$ emprise = ${nf(p.Le, 2)} × ${nf(p.le, 2)} = ${nf(Em, 2)} m²\n$$ murs, cloisons et espaces non décrits = ${nf(Em, 2)} − ${nf(Sh + Sa, 2)} = ${nf(Em - Sh - Sa, 2)} m²\n$$ rapport surface habitable / emprise = ${nf(Sh, 2)} / ${nf(Em, 2)} = ${nf(Sh/Em, 3)}\n${Sh/Em >= .75 ? 'Rapport satisfaisant (0,75 à 0,90 pour une maison bien conçue).' : 'Rapport faible : beaucoup de surface perdue en murs, circulations ou annexes.'}`, ask:[{l:'Emprise', v:Em, u:'m²'}, {l:'Rapport', v:Sh/Em, abs:.005}]});
  st.push({t:'Surface de plancher', md:`On mesure chaque niveau au nu intérieur des murs de façade (épaisseur ${nf(p.ep)} cm) :\n$$ par niveau = (${nf(p.Le, 2)} − 2 × ${nf(e, 2)}) × (${nf(p.le, 2)} − 2 × ${nf(e, 2)}) = ${nf(Sp1, 2)} m²\n$$ surface de plancher = ${p.niv} × ${nf(Sp1, 2)} = ${nf(Sp, 2)} m²\n(La définition exacte de la surface de plancher dépend du règlement : vérifier les déductions admises, par exemple pour les escaliers ou les locaux techniques.)`, ask:[{l:'Surface de plancher', v:Sp, u:'m²'}]});
  const bar = (y, lab, v, mx, ok) => T(20, y + 13, lab, {s:12, b:1}) + Rc(80, y, 300, 18, {c:C.GR, w:1}) + Rc(80, y, Math.min(1.25, v/mx)*240, 18, {f:ok ? C.OK : C.RD, c:ok ? C.OK : C.RD, w:1}) + Ln(320, y - 4, 320, y + 22, {c:C.INK, w:2}) + T(326, y - 6, 'max ' + nf(mx, 2), {s:10, c:C.GR}) + T(88, y + 13, nf(v, 2), {s:11, c:'#fff', b:1});
  st.push({t:'CES, COS et conformité', md:`$$ CES = emprise / parcelle = ${nf(Em, 2)} / ${nf(p.S)} = ${nf(ces, 3)}   ${ok1 ? '≤' : '>'} ${nf(p.ces, 2)} ${ok1 ? '✓' : '✗'}\n$$ COS = surface de plancher / parcelle = ${nf(Sp, 2)} / ${nf(p.S)} = ${nf(cos, 3)}   ${ok2 ? '≤' : '>'} ${nf(p.cos, 2)} ${ok2 ? '✓' : '✗'}\n\n${ok1 && ok2 ? '**Le projet respecte le CES et le COS.** Il reste à vérifier les reculs et la hauteur sur le plan de masse.' : `**Le projet n'est pas conforme** : ${!ok1 ? `réduire l'emprise à ${nf(p.ces*p.S, 1)} m² au plus` : ''}${!ok1 && !ok2 ? ' et ' : ''}${!ok2 ? `réduire la surface de plancher à ${nf(p.cos*p.S, 1)} m² au plus (moins de niveaux ou bâtiment plus petit)` : ''}.`}`, ask:[{l:'CES', v:ces, abs:.005}, {l:'COS', v:cos, abs:.005}], html:`<div class="solfig">${SV(440, 90, bar(18, 'CES', ces, p.ces, ok1) + bar(56, 'COS', cos, p.cos, ok2), 'CES et COS')}</div>`});
  return {steps:st, bilan:`Surface habitable **${nf(Sh, 2)} m²** par niveau${Sa ? ` (+ ${nf(Sa, 2)} m² d'annexes)` : ''}, emprise **${nf(Em, 2)} m²** (rapport ${nf(Sh/Em, 2)}), surface de plancher **${nf(Sp, 2)} m²** ; CES = **${nf(ces, 2)}**, COS = **${nf(cos, 2)}** → ${ok1 && ok2 ? '**conforme**' : '**non conforme**'}.`};
 }});

S.reg({id:'des-niveaux', mat:'dessin', mats:['dessin', 'tech'], niv:2, titre:'Cotes de niveau d\'un bâtiment (coupe et façade)', resume:'Hauteur d\'étage, niveaux finis et bruts de chaque plancher, toiture terrasse et acrotère, hauteur totale, altitudes et marches d\'accès.',
 ia:'{"alt":18.45,"tn":-0.5,"n":2,"hsp":2.8,"pl":20,"rev":6,"et":8,"acr":0.6,"hm":17} — alt altitude du ±0,00 (m), tn niveau du terrain naturel relatif au ±0,00 (m, négatif), n nombre de niveaux, hsp hauteur sous plafond (m), pl épaisseur des planchers (cm), rev revêtement + chape (cm), et forme de pente + étanchéité (cm), acr hauteur d\'acrotère (m), hm hauteur maximale de marche (cm)',
 champs:[{k:'alt', l:'Altitude du ±0,00 (sol fini du RDC)', u:'m'}, {k:'tn', l:'Terrain naturel (niveau relatif)', u:'m'}, {k:'n', l:'Nombre de niveaux (RDC compris)'}, {k:'hsp', l:'Hauteur sous plafond', u:'m'}, {k:'pl', l:'Épaisseur des planchers', u:'cm'}, {k:'rev', l:'Revêtement + chape', u:'cm'}, {k:'et', l:'Forme de pente + étanchéité', u:'cm'}, {k:'acr', l:'Acrotère au-dessus de l\'étanchéité', u:'m'}, {k:'hm', l:'Hauteur maximale de marche', u:'cm'}],
 ex:{alt:18.45, tn:-.5, n:2, hsp:2.8, pl:20, rev:6, et:8, acr:.6, hm:17},
 rnd:() => ({alt:R.s(5, 60, .05), tn:-R.s(.15, .9, .05), n:R.i(1, 4), hsp:R.p([2.7, 2.8, 2.9, 3]), pl:R.p([16, 20, 25]), rev:R.p([5, 6, 8]), et:R.p([6, 8, 10]), acr:R.p([.4, .6, 1]), hm:R.p([16, 17, 18])}),
 enonce:p => `Un bâtiment de **${p.n} niveau${p.n > 1 ? 'x' : ''}** (R${p.n > 1 ? '+' + (p.n - 1) : ''}) a une toiture terrasse. ±0,00 = sol fini du RDC = altitude **${nf(p.alt, 2)} m** ; terrain naturel à **${nf(p.tn, 2)}**. HSP **${nf(p.hsp, 2)} m** ; planchers de **${nf(p.pl)} cm** ; revêtements **${nf(p.rev)} cm** ; forme de pente + étanchéité **${nf(p.et)} cm** ; acrotère de **${nf(p.acr, 2)} m**.\n\n1. Calculer la hauteur d'étage.\n2. Établir le tableau des niveaux (sols finis, dessous et dessus des planchers).\n3. Calculer la hauteur totale au-dessus du terrain et l'altitude du dessus de l'acrotère.\n4. Calculer le nombre de marches d'accès (hauteur ≤ ${nf(p.hm)} cm).`,
 solve(p){
  need(p, [['alt', 'Altitude', -500, 9000], ['tn', 'Terrain naturel', -5, 5], ['n', 'Nombre de niveaux', 1, 40], ['hsp', 'HSP', 2, 6], ['pl', 'Épaisseur des planchers', 8, 60], ['rev', 'Revêtement', 0, 20], ['et', 'Étanchéité', 0, 40], ['acr', 'Acrotère', 0, 2], ['hm', 'Hauteur de marche', 12, 21]]);
  const n = Math.round(p.n), he = p.hsp + p.pl/100 + p.rev/100, L = [], st = [];
  for(let i = 0; i < n; i++){ const sf = i*he; L.push({nom:i ? `Étage ${i}` : 'RDC', sf, dp:sf + p.hsp, db:sf + p.hsp + p.pl/100}); }
  const top = L[n - 1], dalle = top.db, etan = dalle + p.et/100, acr = etan + p.acr, H = acr - p.tn, nm = p.tn < 0 ? Math.ceil(-p.tn*100/p.hm - 1e-9) : 0;
  const sg = v => (v > .0005 ? '+' : v < -.0005 ? '−' : '±') + Math.abs(v).toFixed(2).replace('.', ',');
  st.push({t:'Hauteur d\'étage', md:`$$ hauteur d'étage = HSP + plancher + revêtement = ${nf(p.hsp, 2)} + ${nf(p.pl/100, 2)} + ${nf(p.rev/100, 2)} = ${nf(he, 3)} m\nC'est la distance entre deux **sols finis** successifs.`, ask:[{l:'Hauteur d\'étage', v:he, u:'m', abs:.005}]});
  st.push({t:'Tableau des niveaux', md:`${tb(['Niveau', 'Sol fini', 'Dessous du plancher haut', 'Dessus brut du plancher haut'], L.map(r => [r.nom, sg(r.sf), sg(r.dp), sg(r.db)]))}\n\nToiture terrasse : dessus brut de la dalle **${sg(dalle)}**, dessus de l'étanchéité **${sg(etan)}**, dessus de l'acrotère **${sg(acr)}**.\n\nLe sol fini d'un niveau = dessus brut du plancher + revêtement (${nf(p.rev)} cm).`, ask:[...(n > 1 ? [{l:`Sol fini du niveau ${n - 1}`, v:top.sf, u:'m', abs:.005}] : []), {l:'Dessus de l\'acrotère', v:acr, u:'m', abs:.005}]});
  const k = Math.min(30, 230/(H + .6)), xb = 150, wb = 200, Y = z => 250 - (z - p.tn)*k - 10;
  let fg = `<rect x="0" y="${Y(p.tn).toFixed(1)}" width="560" height="30" fill="url(#shh)"/>` + Ln(0, Y(p.tn), 560, Y(p.tn), {w:1.6}) + Rc(xb, Y(acr), 8, Y(p.tn) - Y(acr), {f:C.CO}) + Rc(xb + wb - 8, Y(acr), 8, Y(p.tn) - Y(acr), {f:C.CO});
  L.forEach(r => { fg += Rc(xb, Y(r.db), wb, (p.pl/100)*k, {f:C.CO}); }) ; fg += Rc(xb, Y(0), wb, 3, {f:C.CO});
  const lv = (z, t, c) => Ln(xb - 90, Y(z), xb - 4, Y(z), {c:C.GR, w:1}) + Pth(`M ${xb - 70} ${Y(z).toFixed(1)} l -6 -9 h 12 z`, {c:c || C.INK, w:1.2}) + T(xb - 60, Y(z) - 3, t, {s:10.5, b:1, c:c || C.INK});
  fg += lv(0, '±0,00', C.BL) + L.slice(1).map(r => lv(r.sf, sg(r.sf))).join('') + lv(acr, sg(acr)) + Ln(xb + wb + 4, Y(p.tn), xb + wb + 90, Y(p.tn), {c:C.GR, w:1}) + T(xb + wb + 20, Y(p.tn) - 4, 'TN ' + sg(p.tn), {s:10.5, b:1}) + Dim(xb + wb + 40, Y(acr), xb + wb + 40, Y(p.tn), 'H = ' + nf(H, 2) + ' m');
  st.push({t:'Hauteur totale et altitudes', md:`$$ H = dessus de l'acrotère − TN = ${nf(acr, 2)} − (${nf(p.tn, 2)}) = ${nf(H, 2)} m\n$$ altitude du dessus de l'acrotère = ${nf(p.alt, 2)} + ${nf(acr, 2)} = ${nf(p.alt + acr, 2)} m\n$$ altitude du terrain naturel = ${nf(p.alt, 2)} + (${nf(p.tn, 2)}) = ${nf(p.alt + p.tn, 2)} m\nC'est la hauteur à comparer à la hauteur maximale autorisée par le règlement d'urbanisme.`, ask:[{l:'Hauteur totale H', v:H, u:'m', abs:.01}], html:`<div class="solfig">${SV(560, 270, fg, 'Niveaux en coupe')}</div>`});
  st.push({t:'Marches d\'accès', md:p.tn < 0 ? `Hauteur à monter du terrain au sol fini : ${nf(-p.tn*100, 0)} cm.\n$$ n = ${nf(-p.tn*100, 0)} / ${nf(p.hm)} = ${nf(-p.tn*100/p.hm, 2)}  →  ${nm} marche${nm > 1 ? 's' : ''} de ${nf(-p.tn*100/nm, 1)} cm\n(on arrondit au nombre entier supérieur pour ne pas dépasser ${nf(p.hm)} cm ; le seuil peut aussi être traité par un perron ou une rampe à 5 % au plus pour les personnes à mobilité réduite : longueur ${nf(-p.tn/.05, 2)} m).` : `Le sol fini est au niveau ou en dessous du terrain : pas de marche, mais il faut **protéger le bâtiment des eaux de ruissellement** (pente du terrain vers l'extérieur, caniveau, seuil surélevé).`, ask:[{l:'Nombre de marches', v:nm, abs:.01}]});
  return {steps:st, bilan:`Hauteur d'étage **${nf(he, 2)} m** ; ${n > 1 ? `sol fini du dernier niveau **${sg(top.sf)}**, ` : ''}dessus de dalle de toiture ${sg(dalle)}, acrotère **${sg(acr)}** (altitude ${nf(p.alt + acr, 2)} m) ; hauteur totale **${nf(H, 2)} m** ; ${nm ? `**${nm} marches** d'accès` : 'pas de marche d\'accès'}.`};
 }});

S.reg({id:'des-toiture4', mat:'dessin', mats:['dessin', 'tech', 'metre'], niv:3, titre:'Toiture à quatre pans : faîtage, arêtiers en vraie grandeur et surfaces', resume:'Contour d\'égout, faîtage, hauteur, rampant, arêtier en plan et en vraie grandeur, surfaces des long pans et des croupes, pannes et descentes d\'eaux pluviales.',
 ia:'{"L":15,"l":9,"d":0.8,"pe":22,"ep":1.2} — L et l longueur et largeur du bâtiment aux nus extérieurs des murs (m), d débord (m), pe pente (°), ep entraxe maximal des pannes (m)',
 champs:[{k:'L', l:'Longueur du bâtiment (nus extérieurs)', u:'m'}, {k:'l', l:'Largeur du bâtiment (nus extérieurs)', u:'m'}, {k:'d', l:'Débord de toiture', u:'m'}, {k:'pe', l:'Pente des versants', u:'°'}, {k:'ep', l:'Entraxe maximal des pannes', u:'m'}],
 ex:{L:15, l:9, d:.8, pe:22, ep:1.2},
 rnd:() => ({L:R.s(10, 22, .1), l:R.s(7, 11, .1), d:R.p([.5, .6, .8, 1]), pe:R.s(15, 35, 1), ep:R.p([1, 1.2, 1.5])}),
 enonce:p => `Un bâtiment rectangulaire de **${nf(p.L)} × ${nf(p.l)} m** reçoit une toiture à **quatre pans** de pente **${nf(p.pe)}°**, avec des débords de **${nf(p.d)} m** tout autour. Les pannes sont espacées au plus de ${nf(p.ep)} m.\n\n1. Calculer le contour d'égout, la longueur du faîtage et sa hauteur.\n2. Calculer le rampant.\n3. Calculer l'arêtier en plan, en vraie grandeur, et sa pente.\n4. Calculer les surfaces des pans et la surface totale de couverture.\n5. Déterminer le nombre de files de pannes par versant et de descentes d'eaux pluviales.`,
 solve(p){
  need(p, [['L', 'Longueur', 2, 200], ['l', 'Largeur', 2, 100], ['d', 'Débord', 0, 3], ['pe', 'Pente', 3, 70], ['ep', 'Entraxe des pannes', .3, 5]]);
  const L0 = Math.max(p.L, p.l), l0 = Math.min(p.L, p.l), a = rad(p.pe), Le = L0 + 2*p.d, le = l0 + 2*p.d, fa = Le - le, f = le/2*Math.tan(a), fm = l0/2*Math.tan(a), r = le/2/Math.cos(a);
  const ap = le/2*Math.SQRT2, avg = Math.hypot(ap, f), b = deg(Math.atan(f/ap)), Slp = (Le + fa)/2*r, Scr = le*r/2, Stot = 2*Slp + 2*Scr, Sch = Le*le/Math.cos(a), np = Math.ceil(r/p.ep - 1e-9) + 1, nd = Math.max(2, Math.ceil(Le*le/90)), st = [];
  st.push({t:'Contour d\'égout et faîtage', md:`$$ contour d'égout = (${nf(L0)} + 2 × ${nf(p.d)}) × (${nf(l0)} + 2 × ${nf(p.d)}) = ${nf(Le, 2)} × ${nf(le, 2)} m\nAvec des pentes égales, les arêtiers sont à 45° en plan : chacun « consomme » une demi-largeur à chaque bout.\n$$ faîtage = ${nf(Le, 2)} − ${nf(le, 2)} = ${nf(fa, 2)} m\n$$ hauteur au-dessus de l'égout : f = (le/2) × tan α = ${nf(le/2, 2)} × ${nf(Math.tan(a), 4)} = ${nf(f, 3)} m\n(au-dessus du haut des murs : (l/2) × tan α = ${nf(fm, 3)} m ; pente ${nf(Math.tan(a)*100, 1)} %)`, ask:[{l:'Faîtage', v:fa, u:'m', abs:.01}, {l:'f', v:f, u:'m', abs:.005}]});
  st.push({t:'Rampant', md:`$$ rampant = (le/2) / cos α = ${nf(le/2, 2)} / ${nf(Math.cos(a), 4)} = ${nf(r, 3)} m\nC'est la longueur des tôles ou bacs d'un long pan (à majorer du dépassement en égout et du recouvrement au faîtage).`, ask:[{l:'Rampant', v:r, u:'m', abs:.005}]});
  const k = Math.min(300/Le, 180/le), x0 = 30, y0 = 30, W = Le*k, Hh = le*k, xr = x0 + W + 40, bas = ap*k*.8;
  const fig = Rc(x0, y0, W, Hh, {w:2}) + Rc(x0 + p.d*k, y0 + p.d*k, L0*k, l0*k, {c:C.GR, w:1, d:'5 4'}) + Ln(x0 + Hh/2, y0 + Hh/2, x0 + W - Hh/2, y0 + Hh/2, {c:C.RD, w:3}) + [[x0, y0], [x0, y0 + Hh], [x0 + W, y0], [x0 + W, y0 + Hh]].map(([x, y]) => Ln(x, y, x < x0 + W/2 ? x0 + Hh/2 : x0 + W - Hh/2, y0 + Hh/2, {w:2})).join('') +
   T(x0 + W/2, y0 + Hh/2 - 6, 'faîtage ' + nf(fa, 2) + ' m', {a:'middle', s:10.5, c:C.RD, b:1}) + Dim(x0, y0 + Hh + 14, x0 + W, y0 + Hh + 14, nf(Le, 2) + ' m') + Dim(x0 - 14, y0, x0 - 14, y0 + Hh, nf(le, 2) + ' m') +
   Ln(xr, y0 + Hh, xr + bas, y0 + Hh, {w:1.6}) + Ln(xr + bas, y0 + Hh, xr + bas, y0 + Hh - f*k*.8, {c:C.BL, w:1.6}) + Ln(xr, y0 + Hh, xr + bas, y0 + Hh - f*k*.8, {c:C.RD, w:2.6}) + T(xr + bas/2, y0 + Hh + 16, 'plan ' + nf(ap, 2), {a:'middle', s:10.5}) + T(xr + bas + 6, y0 + Hh - f*k*.4, 'f', {s:11, c:C.BL, b:1}) + T(xr + bas/2 - 4, y0 + Hh - f*k*.4 - 10, 'VG ' + nf(avg, 2), {a:'middle', s:10.5, c:C.RD, b:1});
  st.push({t:'Arêtier en vraie grandeur', md:`$$ arêtier en plan = (le/2) × √2 = ${nf(le/2, 2)} × 1,4142 = ${nf(ap, 3)} m\nOn rabat l'arêtier : triangle rectangle de base ${nf(ap, 3)} m et de hauteur f = ${nf(f, 3)} m.\n$$ vraie grandeur = √(${nf(ap, 3)}² + ${nf(f, 3)}²) = ${nf(avg, 3)} m\n$$ pente de l'arêtier : β = arctan(f / plan) = ${nf(b, 1)}°  (plus faible que celle des versants)`, ask:[{l:'Arêtier en vraie grandeur', v:avg, u:'m', abs:.01}], html:`<div class="solfig">${SV(xr + bas + 60, y0 + Hh + 40, fig, 'Plan de toiture et rabattement')}</div>`});
  st.push({t:'Surfaces de couverture', md:`- **long pan** (trapèze) : $$ (${nf(Le, 2)} + ${nf(fa, 2)}) / 2 × ${nf(r, 3)} = ${nf(Slp, 2)} m²\n- **croupe** (triangle) : $$ ${nf(le, 2)} × ${nf(r, 3)} / 2 = ${nf(Scr, 2)} m²\n$$ total = 2 × ${nf(Slp, 2)} + 2 × ${nf(Scr, 2)} = ${nf(Stot, 2)} m²\nVérification : $$ surface en plan / cos α = ${nf(Le*le, 2)} / ${nf(Math.cos(a), 4)} = ${nf(Sch, 2)} m² ✓`, ask:[{l:'Surface totale', v:Stot, u:'m²'}]});
  st.push({t:'Pannes et descentes d\'eaux pluviales', md:`$$ files de pannes par versant = rampant / entraxe + 1 = ${nf(r, 2)} / ${nf(p.ep)} + 1 → ${np}\n(sablière et faîtière comprises ; sur les croupes, les pannes sont recoupées le long des arêtiers).\n$$ descentes Ø 100 ≈ surface en plan / 80 à 100 m² = ${nf(Le*le, 1)} / 90 → ${nd}\nOn en place souvent une à chaque angle (4) pour raccourcir le parcours de l'eau dans les gouttières.`, ask:[{l:'Files de pannes par versant', v:np, abs:.01}]});
  return {steps:st, bilan:`Égout ${nf(Le, 2)} × ${nf(le, 2)} m ; faîtage **${nf(fa, 2)} m** à **${nf(f, 2)} m** au-dessus de l'égout ; rampant **${nf(r, 2)} m** ; arêtier ${nf(ap, 2)} m en plan, **${nf(avg, 2)} m** en vraie grandeur (${nf(b, 1)}°) ; couverture **${nf(Stot, 1)} m²** ; ${np} files de pannes par versant, ${nd} descentes au minimum.`};
 }});

S.reg({id:'des-nomenclature', mat:'dessin', mats:['dessin', 'ba', 'metre'], niv:2, titre:'Nomenclature des aciers d\'un plan de ferraillage', resume:'Masses linéiques, longueurs totales et masses par repère, récapitulatif par diamètre, barres de 12 m à commander et ratio d\'acier.',
 ia:'{"t":[{"rep":"1","n":3,"d":12,"L":4.9}],"V":0.376,"pc":5} — t liste des repères (rep repère, n nombre de barres, d diamètre en mm, L longueur unitaire développée en m), V volume de béton de l\'élément (m³, 0 si inconnu), pc pourcentage de chutes',
 champs:[{k:'t', l:'Repères de la nomenclature', t:'tab', min:1, max:20, cols:[{k:'rep', l:'Repère', t:'txt', w:50}, {k:'n', l:'Nombre', w:56}, {k:'d', l:'Ø', u:'mm', w:50}, {k:'L', l:'Long. unitaire', u:'m', w:70}], row:rows => ({rep:String(rows.length + 1), n:2, d:10, L:3})}, {k:'V', l:'Volume de béton de l\'élément (0 si inconnu)', u:'m³'}, {k:'pc', l:'Chutes', u:'%'}],
 ex:{t:[{rep:'1', n:3, d:12, L:4.9}, {rep:'2', n:2, d:10, L:4.9}, {rep:'3', n:25, d:6, L:1.1}], V:.376, pc:5},
 rnd:() => ({t:[{rep:'1', n:R.i(2, 5), d:R.p([12, 14, 16]), L:R.s(3, 7, .05)}, {rep:'2', n:2, d:R.p([8, 10, 12]), L:R.s(3, 7, .05)}, {rep:'3', n:R.i(15, 45), d:R.p([6, 8]), L:R.s(.8, 1.6, .05)}], V:R.s(.2, 1.5, .01), pc:R.p([5, 8, 10])}),
 enonce:p => `Établir la nomenclature des aciers d'un élément en béton armé${p.V > 0 ? ` (volume de béton ${nf(p.V, 3)} m³)` : ''} :\n\n${tb(['Repère', 'Nombre', 'Ø (mm)', 'Longueur unitaire (m)'], p.t.map(r => [r.rep, r.n, r.d, nf(+r.L, 2)]))}\n\n1. Calculer la masse linéique de chaque diamètre.\n2. Calculer la longueur totale et la masse de chaque repère, puis la masse totale.\n3. Récapituler par diamètre et calculer le nombre de barres de 12 m à commander (chutes ${nf(p.pc)} %).${p.V > 0 ? '\n4. Calculer le ratio d\'acier en kg/m³.' : ''}`,
 solve(p){
  need(p, [['V', 'Volume', 0, 10000], ['pc', 'Chutes', 0, 50]]);
  const rows = p.t.map(r => ({rep:r.rep || '?', n:Math.round(+r.n), d:+r.d, L:+r.L})); if(rows.some(r => !(r.n > 0) || !(r.d >= 4 && r.d <= 50) || !(r.L > 0))) throw new Err('Nombre, diamètre (4 à 50 mm) ou longueur invalide.');
  const ml = d => .00617*d*d; rows.forEach(r => { r.Lt = r.n*r.L; r.m = r.Lt*ml(r.d); });
  const M = rows.reduce((a, r) => a + r.m, 0), ds = [...new Set(rows.map(r => r.d))].sort((a, b) => a - b), rec = ds.map(d => { const Lt = rows.filter(r => r.d === d).reduce((a, r) => a + r.Lt, 0); return {d, Lt, m:Lt*ml(d), nb:Math.ceil(Lt*(1 + p.pc/100)/12 - 1e-9)}; }), st = [];
  st.push({t:'Masses linéiques', md:`Une barre de diamètre Ø (mm) a une section π Ø²/4 et l'acier pèse 7 850 kg/m³ :\n$$ masse linéique = 7 850 × π Ø² / 4 × 10⁻⁶ = 0,00617 × Ø²  (kg/m)\n${tb(['Ø (mm)', 'kg/m'], ds.map(d => [d, nf(ml(d), 3)]))}`, ask:[{l:`Masse linéique du Ø${ds[0]}`, v:ml(ds[0]), u:'kg/m', abs:.002}]});
  st.push({t:'Nomenclature par repère', md:`${tb(['Rep.', 'Désignation', 'L unitaire', 'L totale', 'kg/m', 'Masse'], rows.map(r => [r.rep, `${r.n} HA${r.d}`, nf(r.L, 2) + ' m', nf(r.Lt, 2) + ' m', nf(ml(r.d), 3), nf(r.m, 2) + ' kg']))}\n\n$$ masse totale = ${nf(M, 2)} kg\nLa longueur unitaire est la longueur **développée** (crochets et retours compris), lue sur le schéma de façonnage.`, ask:[{l:`Masse du repère ${rows[0].rep}`, v:rows[0].m, u:'kg'}, {l:'Masse totale', v:M, u:'kg'}], hint:'Longueur totale = nombre × longueur unitaire ; masse = longueur totale × masse linéique.'});
  st.push({t:'Récapitulatif et commande', md:`${tb(['Ø', 'Longueur totale', 'Masse', `Barres de 12 m (+ ${nf(p.pc)} %)`], rec.map(r => ['HA' + r.d, nf(r.Lt, 2) + ' m', nf(r.m, 2) + ' kg', r.nb]))}\n\nLes aciers se vendent en barres de **12 m** (ou au poids) : on ajoute un pourcentage de **chutes** et on optimise les coupes (plan de débit) pour réutiliser les restes.`, ask:[{l:`Barres de 12 m en HA${rec[0].d}`, v:rec[0].nb, abs:.01}]});
  if(p.V > 0) st.push({t:'Ratio d\'acier', md:`$$ ratio = ${nf(M, 2)} / ${nf(p.V, 3)} = ${nf(M/p.V, 1)} kg/m³\nOrdres de grandeur : semelles 30 à 60 kg/m³, poteaux et poutres 80 à 150 kg/m³, dalles 50 à 90 kg/m³. ${M/p.V < 25 ? 'Ratio très faible : vérifier que toutes les armatures sont comptées.' : M/p.V > 250 ? 'Ratio très élevé : vérifier les longueurs et les diamètres.' : 'Valeur plausible.'}`, ask:[{l:'Ratio', v:M/p.V, u:'kg/m³'}]});
  return {steps:st, bilan:`Masse totale **${nf(M, 1)} kg** ; ${rec.map(r => `HA${r.d} : ${nf(r.Lt, 1)} m (${r.nb} barre${r.nb > 1 ? 's' : ''} de 12 m)`).join(' ; ')}${p.V > 0 ? ` ; ratio **${nf(M/p.V, 0)} kg/m³**` : ''}.`};
 }});

S.reg({id:'des-assainissement', mat:'dessin', mats:['dessin', 'mdf', 'tech'], niv:3, titre:'Profil en long d\'un réseau d\'assainissement (fils d\'eau)', resume:'Fils d\'eau de chaque regard, profondeurs, pente maximale disponible et vérification du raccordement au collecteur.',
 ia:'{"fe0":24.3,"p":2,"t":[{"n":"R1","d":0,"tp":24.8},{"n":"R2","d":12,"tp":24.7}],"fec":23.6,"marge":0.1,"pmin":0.5} — fe0 fil d\'eau du premier regard (m), p pente souhaitée (%), t regards (n nom, d distance depuis le regard précédent en m, la première valant 0, tp cote du tampon en m), fec fil d\'eau du collecteur d\'arrivée (0 si sans objet), marge chute minimale au-dessus du collecteur (m), pmin profondeur minimale d\'un regard (m)',
 champs:[{k:'fe0', l:'Fil d\'eau du premier regard', u:'m'}, {k:'p', l:'Pente souhaitée', u:'%'}, {k:'t', l:'Regards (dans le sens de l\'écoulement)', t:'tab', min:2, max:15, cols:[{k:'n', l:'Regard', t:'txt', w:50}, {k:'d', l:'Distance depuis le précédent', u:'m', w:80}, {k:'tp', l:'Cote du tampon', u:'m', w:70}], row:rows => ({n:'R' + (rows.length + 1), d:10, tp:rows.length ? +rows[rows.length - 1].tp : 10})},
  {k:'fec', l:'Fil d\'eau du collecteur d\'arrivée (0 si sans objet)', u:'m'}, {k:'marge', l:'Chute minimale au-dessus du collecteur', u:'m'}, {k:'pmin', l:'Profondeur minimale d\'un regard', u:'m'}],
 ex:{fe0:24.3, p:2, t:[{n:'R1', d:0, tp:24.8}, {n:'R2', d:12, tp:24.7}, {n:'R3', d:15, tp:24.55}, {n:'RB', d:8, tp:24.4}], fec:23.6, marge:.1, pmin:.5},
 rnd:() => { const tp0 = R.s(10, 40, .05); let tp = tp0; const t = [{n:'R1', d:0, tp:tp0}]; const nr = R.i(3, 5); for(let i = 1; i < nr; i++){ tp = +(tp - R.s(0, .3, .05)).toFixed(2); t.push({n:i === nr - 1 ? 'RB' : 'R' + (i + 1), d:R.s(6, 25, 1), tp}); } const L = t.reduce((a, r) => a + r.d, 0); return {fe0:+(tp0 - R.s(.4, .7, .05)).toFixed(2), p:R.p([1, 1.5, 2, 2.5]), t, fec:+(tp0 - R.s(.5, .7, .05) - L*R.s(.012, .03, .001)).toFixed(2), marge:.1, pmin:.5}; },
 enonce:p => `Un collecteur PVC part du regard ${p.t[0].n} (fil d'eau **${nf(p.fe0, 2)}**) avec une pente souhaitée de **${nf(p.p)} %**. Regards successifs :\n\n${tb(['Regard', 'Distance depuis le précédent (m)', 'Cote du tampon'], p.t.map(r => [r.n, nf(+r.d, 2), nf(+r.tp, 2)]))}\n\n${p.fec > 0 ? `Le dernier regard se raccorde à un collecteur dont le fil d'eau est à **${nf(p.fec, 2)}** (chute minimale ${nf(p.marge, 2)} m). ` : ''}Profondeur minimale d'un regard : ${nf(p.pmin, 2)} m.\n\n1. Calculer les fils d'eau de chaque regard avec la pente souhaitée.\n2. Calculer les profondeurs des regards.\n3. ${p.fec > 0 ? 'Vérifier le raccordement et calculer la pente maximale possible ; conclure.' : 'Vérifier que la pente respecte le minimum de 1 %.'}`,
 solve(p){
  need(p, [['fe0', 'Fil d\'eau de départ', -500, 9000], ['p', 'Pente', .1, 20], ['fec', 'Fil d\'eau du collecteur', -500, 9000], ['marge', 'Chute minimale', 0, 3], ['pmin', 'Profondeur minimale', 0, 5]]);
  const rs = p.t.map((r, i) => ({n:r.n || 'R' + (i + 1), d:i ? +r.d : 0, tp:+r.tp})); if(rs.some((r, i) => (i && !(r.d > 0)) || !isFinite(r.tp))) throw new Err('Distance ou cote de tampon invalide.');
  if(rs[0].tp < p.fe0) throw new Err('Le fil d\'eau de départ est au-dessus du tampon du premier regard.');
  const fill = pc => { let fe = p.fe0, x = 0; return rs.map(r => { x += r.d; fe -= pc/100*r.d; return {...r, x, fe:r === rs[0] ? p.fe0 : fe}; }); };
  const A1 = fill(p.p), Lt = A1[A1.length - 1].x, last = A1[A1.length - 1], hasC = p.fec > 0, feMax = hasC ? p.fec + p.marge : null, pMax = hasC ? (p.fe0 - feMax)/Lt*100 : null;
  if(hasC && !(pMax > 0)) throw new Err('Le collecteur est plus haut que le départ : écoulement gravitaire impossible (prévoir une station de relevage).');
  const ok = !hasC || last.fe >= feMax - 1e-6, pr = ok ? p.p : Math.floor(pMax*10)/10, A = ok ? A1 : fill(pr), st = [];
  st.push({t:'Fils d\'eau avec la pente souhaitée', md:`$$ FE aval = FE amont − pente × longueur\n${tb(['Regard', 'Distance cumulée (m)', 'Calcul', 'FE'], A1.map((r, i) => [r.n, nf(r.x, 2), i ? `${nf(A1[i - 1].fe, 3)} − ${nf(p.p/100, 3)} × ${nf(r.d, 2)}` : 'départ', nf(r.fe, 3)]))}`, ask:[{l:`FE de ${last.n}`, v:last.fe, u:'m', abs:.005}]});
  st.push({t:'Raccordement et pente retenue', md:hasC ? `Le fil d'eau d'arrivée doit rester au moins ${nf(p.marge, 2)} m au-dessus de celui du collecteur : $$ FE minimal = ${nf(p.fec, 2)} + ${nf(p.marge, 2)} = ${nf(feMax, 2)}\n$$ pente maximale = (${nf(p.fe0, 2)} − ${nf(feMax, 2)}) / ${nf(Lt, 2)} = ${nf(pMax, 2)} %\n${ok ? `Avec ${nf(p.p)} %, le FE d'arrivée (${nf(last.fe, 3)}) est au-dessus du minimum : **la pente souhaitée convient** ✓.` : `Avec ${nf(p.p)} %, le FE d'arrivée (${nf(last.fe, 3)}) serait trop bas : on retient **${nf(pr, 1)} %**.`}${pr < 1 ? `\n\n> [!attention] Pente insuffisante\n> La pente retenue est inférieure à **1 %** : il faut approfondir le départ, raccourcir le tracé ou prévoir une **station de relevage**.` : ''}` : `Pas de collecteur imposé : la pente de ${nf(p.p)} % ${p.p >= 1 ? 'respecte le minimum de **1 %** ✓ (2 à 3 % conseillés pour les eaux usées).' : 'est **inférieure à 1 %** : risque de dépôts et de bouchages.'}`, ask:hasC ? [{l:'Pente maximale', v:pMax, u:'%', abs:.02}] : []});
  const zmin = Math.min(...A.map(r => r.fe)) - .2, zmax = Math.max(...A.map(r => r.tp)) + .2, X = x => 60 + x/Lt*460, Y = z => 30 + (zmax - z)/(zmax - zmin)*180;
  const fg = Pth('M ' + A.map(r => `${X(r.x).toFixed(1)} ${Y(r.tp).toFixed(1)}`).join(' L '), {c:'#7A5C2E', w:2}) + Pth('M ' + A.map(r => `${X(r.x).toFixed(1)} ${Y(r.fe).toFixed(1)}`).join(' L '), {c:C.BL, w:2.4}) +
   A.map(r => Rc(X(r.x) - 6, Y(r.tp), 12, Y(r.fe) - Y(r.tp) + 4, {f:'#fff', w:1.4}) + T(X(r.x), Y(r.tp) - 6, r.n, {a:'middle', s:11, b:1}) + T(X(r.x), 236, nf(r.fe, 2), {a:'middle', s:10, c:C.BL}) + T(X(r.x), 250, nf(r.tp - r.fe, 2) + ' m', {a:'middle', s:10, b:1})).join('') + T(8, 236, 'FE', {s:10, c:C.BL}) + T(8, 250, 'Prof.', {s:10}) + (hasC ? Ln(X(Lt) - 20, Y(p.fec), X(Lt) + 30, Y(p.fec), {c:C.RD, w:1.4, d:'5 3'}) + T(X(Lt) + 32, Y(p.fec) + 4, 'collecteur', {s:9.5, c:C.RD}) : '');
  const prof = A.map(r => r.tp - r.fe), low = A.filter((r, i) => prof[i] < p.pmin - 1e-6);
  st.push({t:'Profondeurs des regards', md:`$$ profondeur = cote du tampon − FE\n${tb(['Regard', 'Tampon', `FE (${nf(pr, 1)} %)`, 'Profondeur'], A.map((r, i) => [r.n, nf(r.tp, 2), nf(r.fe, 3), nf(prof[i], 2) + ' m']))}\n\n${low.length ? `Les regards ${low.map(r => r.n).join(', ')} ont moins de ${nf(p.pmin, 2)} m de profondeur : la canalisation risque d'être trop peu couverte (protection mécanique, dalle de répartition sous les passages de véhicules).` : `Toutes les profondeurs dépassent ${nf(p.pmin, 2)} m ✓.`}`, ask:[{l:`Profondeur de ${A[A.length - 1].n}`, v:prof[prof.length - 1], u:'m', abs:.01}], html:`<div class="solfig">${SV(580, 260, fg, 'Profil en long')}</div>`});
  return {steps:st, bilan:`Longueur ${nf(Lt, 1)} m ; pente retenue **${nf(pr, 1)} %**${hasC ? ` (maximum ${nf(pMax, 2)} %)` : ''} ; FE d'arrivée **${nf(A[A.length - 1].fe, 2)}** ; profondeurs de ${nf(Math.min(...prof), 2)} à ${nf(Math.max(...prof), 2)} m.`};
 }});
})();
